import {resonancePoints} from '../resonance-link.js';
import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {RARE_MAKO,carryWayglass,hasWayglass,calibrateWayglass,collectRelic,ownsRelic,canCalibrate,equipRareMako,discoveryGrowth,installWayglassProps,wayglassState} from '../wayglass-model.js';
import {defaultHero,compileTechnique,compileLoadoutTechnique} from '../mako.js';import{nodesFor,availablePoints,nodeState,unlockNode}from '../skill-grid-model.js';import{Battle,makeEnemy}from '../battle.js?v=5.6.0';import{World}from '../world.js';import{findPath}from '../navigation.js';import{fibreAudit,starFibres}from '../kakeya-math.js';
const state=()=>({chapter:2,scene:228,mode:'field',gold:0,bosses:[],recruited:[0],cores:['earth','mend','gale'],supports:['focus'],heroes:Array.from({length:7},(_,i)=>defaultHero(i)),story:{firstCore:true,journal:[]}});
test('Wayglass is earned, portable, unique, and survives save serialization',()=>{const s=state();s.story.firstCore=false;assert.equal(carryWayglass(s),false);s.story.firstCore=true;assert.equal(carryWayglass(s),true);assert.equal(carryWayglass(s),false);const copy=JSON.parse(JSON.stringify(s));assert.ok(hasWayglass(copy));copy.scene=705;assert.ok(hasWayglass(copy));assert.equal(copy.story.journal.length,1);assert.equal(copy.carriedObjects['rook-wayglass'].portable,true);});
test('calibration locates a seam; it does not award Mako, credits or attunement',()=>{const s=state();assert.equal(calibrateWayglass(s,2),false);carryWayglass(s);assert.equal(fibreAudit(starFibres(2),2).covered,3);assert.equal(calibrateWayglass(s,2),true);assert.equal(ownsRelic(s,'anchorheart'),false);assert.equal(s.gold,0);assert.equal(discoveryGrowth(s),0);assert.equal(canCalibrate(s,3),false);s.scene=705;assert.equal(collectRelic(s,'anchorheart'),false);s.scene=228;assert.ok(collectRelic(s,'anchorheart'));assert.equal(collectRelic(s,'anchorheart'),false);assert.equal(discoveryGrowth(s),2);assert.equal(equipRareMako(s,0,0,'anchorheart'),false);});
test('recovery, prerequisite, paid attunement, equipment and battle use one consistent Mako path',()=>{const s=state();carryWayglass(s);calibrateWayglass(s,2);collectRelic(s,'anchorheart');const node=nodesFor(0).find(n=>n.makoId==='anchorheart');assert.equal(nodeState(s,0,node),'locked');assert.equal(unlockNode(s,0,'6:0'),true);const before=availablePoints(s,0);assert.equal(unlockNode(s,0,node.id),true);assert.equal(availablePoints(s,0),before-1);assert.equal(unlockNode(s,0,node.id),false);assert.ok(equipRareMako(s,0,0,'anchorheart'));const h=s.heroes[0];const plain=compileTechnique('earth','focus',{character:0,ap:h.ap.earth}),rare=compileLoadoutTechnique(h.loadout[0],h,s);assert.equal(rare.power,plain.power*1.2);assert.equal(rare.cost,plain.cost+1);assert.equal(rare.interrupt,true);const e=makeEnemy('guard',1,0);Object.assign(h,{x:0,y:0,atb:1});Object.assign(e,{x:1,y:0,armor:30,intent:{left:2}});const b=new Battle({heroes:[h],enemies:[e]});h.atb=1;const mp=h.mp;assert.ok(b.command(h.id,'tech',e.id,rare));assert.equal(h.mp,mp-rare.cost);assert.equal(e.intent,null);assert.ok(e.hp<e.maxHp);const saved=JSON.parse(JSON.stringify(s));assert.equal(compileLoadoutTechnique(saved.heroes[0].loadout[0],saved.heroes[0],saved).makoId,'anchorheart');});
test('undiscovered or unattuned rare slots receive no battle bonus',()=>{const s=state(),h=s.heroes[0];h.loadout[0]={core:'earth',support:'focus',makoId:'anchorheart'};assert.equal(compileLoadoutTechnique(h.loadout[0],h,s).makoId,undefined);const n=nodesFor(0).find(n=>n.makoId==='anchorheart');assert.equal(nodeState(s,0,n),'undiscovered');assert.equal(unlockNode(s,0,n.id),false);});
test('later finds obey story gates and each rare crystal has a real recipe effect',()=>{const s=state();carryWayglass(s);calibrateWayglass(s,2);collectRelic(s,'anchorheart');assert.equal(canCalibrate(s,3),false);s.chapter=5;assert.ok(canCalibrate(s,3));calibrateWayglass(s,3);s.scene=705;collectRelic(s,'mercyglass');s.chapter=7;assert.ok(canCalibrate(s,4));calibrateWayglass(s,4);s.scene=707;collectRelic(s,'stormseed');assert.equal(discoveryGrowth(s),7);for(const r of RARE_MAKO){s.skillGrid??={};s.skillGrid[0]=[r.prerequisite,'mako:'+r.id];s.heroes[0].loadout[0]={core:r.core,support:'focus'};assert.ok(equipRareMako(s,0,0,r.id));const base=compileTechnique(r.core,'focus',{character:0}),rare=compileLoadoutTechnique(s.heroes[0].loadout[0],s.heroes[0],s);assert.equal(rare.power,base.power*r.power);if(r.id==='stormseed')assert.equal(rare.echo,true);if(r.id==='mercyglass')assert.equal(rare.cost,base.cost-1);}});
test('all three physical seams and pickup are reachable; installation is idempotent',()=>{const d=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))),w=new World(d);installWayglassProps(w);installWayglassProps(w);for(const r of RARE_MAKO){const scene=w.scenes.get(r.location),objects=scene.objects.filter(o=>o.wayglassSeam===r.id);assert.equal(objects.length,1);assert.ok(findPath(scene,scene.arrive,objects[0].xy,1).length,r.id);}const work=w.scenes.get(228),o=work.objects.find(o=>o.wayglassPickup);assert.ok(findPath(work,work.arrive,o.xy,1).length);});

test('existing discoveries hydrate into the shared ledger without duplicate growth',()=>{const s=state();s.kakeya={version:2,solved:[2],relics:['anchorheart'],assignments:{}};wayglassState(s);assert.equal(resonancePoints(s),2);wayglassState(s);assert.equal(resonancePoints(s),2);const old=state();old.kakeya={version:1,solved:[2],relics:[],assignments:{}};wayglassState(old);assert.equal(resonancePoints(old),1);assert.equal(old.kakeya.version,2);});

import {wayglassJourney} from '../wayglass-model.js';
test('cinematic progress cues always name the next earned gameplay action',()=>{const s=state();carryWayglass(s);assert.equal(wayglassJourney(s,2).action,'tune');calibrateWayglass(s,2);s.scene=705;assert.equal(wayglassJourney(s,2).at,1);assert.equal(wayglassJourney(s,2).action,'follow');s.scene=228;assert.equal(wayglassJourney(s,2).at,2);collectRelic(s,'anchorheart');assert.equal(wayglassJourney(s,2).action,'grid');assert.equal(wayglassJourney(s,2).steps[3].state,'current');unlockNode(s,0,'6:0');unlockNode(s,0,'mako:anchorheart');assert.equal(wayglassJourney(s,2).action,'craft');equipRareMako(s,0,0,'anchorheart');const j=wayglassJourney(s,2);assert.equal(j.action,'close');assert.ok(j.steps.every(v=>v.state==='done'));});
test('another character’s attunement never displays an unearned equipment cue',()=>{const s=state();carryWayglass(s);calibrateWayglass(s,2);collectRelic(s,'anchorheart');s.recruited.push(1);s.skillGrid={1:['6:0','mako:anchorheart']};s.heroes[1].loadout=[{core:'earth',support:'focus',makoId:'anchorheart'}];assert.equal(wayglassJourney(s,2,0).action,'grid');assert.equal(wayglassJourney(s,2,1).action,'close');});
